"""Small, stable navigation helpers for the public CLI."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Optional

from rich.console import Console
from rich.panel import Panel
from rich.table import Table
import typer


@dataclass(frozen=True)
class CommandDomain:
    title: str
    commands: tuple[str, ...]
    purpose: str


# This is intentionally a small navigation layer, not a second copy of every
# option generated by Typer.
