def show_command_map(console: Optional[Console] = None) -> None:
    """Print the maintained public command families and reliable entry points."""

    target = console or Console()
    target.print()
    target.print(
        Panel(
            "Seven public command domains. Use `--help` on any command for its authoritative options.",
            title="IINTS-AF command map",
            subtitle="Research and education only",
            border_style="cyan",
        )
    )
    table = Table(expand=True, show_lines=True)
    table.add_column("Domain", style="bold white", width=24)
    table.add_column("Reliable entry points", style="cyan", width=45)
    table.add_column("Purpose")
    for domain in COMMAND_DOMAINS:
        table.add_row(domain.title, "\n".join(domain.commands), domain.purpose)
    target.print(table)
    target.print(
        "Use [cyan]iints menu[/cyan] to choose a domain or "
        "[cyan]iints --help[/cyan] for the complete generated command list."
    )


def interactive_menu(console: Optional[Console] = None) -> None:
    """Show navigation without directly invoking Typer command handlers."""

    target = console or Console()
    while True:
        target.print()
        lines = ["Choose a command domain:", ""]
        lines.extend(f"  {index}. {domain.title}" for index, domain in enumerate(COMMAND_DOMAINS, start=1))
        lines.extend(("", "  m. Show the complete command map", "  q. Exit"))
        target.print(Panel("\n".join(lines), title="IINTS-AF navigation", border_style="cyan"))
        choice = typer.prompt("Selection [1-7, m, q]", default="1").strip().lower()
        if choice == "q":
            return
        if choice == "m":
            show_command_map(target)
            continue
        try:
            selected = COMMAND_DOMAINS[int(choice) - 1]
        except (ValueError, IndexError):
            target.print("[red]Unknown selection.[/red]")
            continue
        target.print(
            Panel(
                "\n".join(
                    (*selected.commands, "", "Run any line above, or add `--help` before executing a workflow.")
                ),
                title=selected.title,
                border_style="green",
            )
        )


__all__ = ["COMMAND_DOMAINS", "interactive_menu", "show_command_map"]
